var state={page:'home',tab:'全部游戏',query:'',players:'全部',genre:'全部',current:null,dialog:null,paused:false,slots:[],autoSlot:null,slotMode:'save',loading:false,busy:false,blocked:false,focus:{},orderDraft:null,orderSelected:null,orderMoving:false,dragOrder:null,custom:[],gridPage:0,lastPlaySave:null,systemInfo:null,checkError:null,resourceInfo:null,resourceError:null,resourceLoading:false,wizard:null,gpMore:{},perf:false,lan:null,pendingRestore:null,remoteSeen:{},updateInfo:null,prefs:{volume:70,favorites:[],recent:[],welcome:false,scale:'original',filter:'none',touch:'auto',turbo:true}};
var games=window.GAME_CATALOG.slice(),toastTimer,lastUI=0,gamepadState={},nativeDevices={},lastPadUI=0,launchId=0,gamepadCapture=null,gamepadTest={};
var touchLayer=window.ArcadeTouch||null;
function touchCapable(){return (navigator.maxTouchPoints||0)>0;}
function touchEnabled(){var mode=state.prefs.touch||'auto';return mode==='on'||(mode!=='off'&&touchCapable());}
function touchKind(g){if(ArcadeLib.isHandheld(g))return 'gba';if(ArcadeLib.isMd(g))return 'md';if(ArcadeLib.isSfc(g))return 'sfc';if(ArcadeLib.isArcade(g))return 'arcade';return 'nes';}
