/* 屏幕按键自定义：位置用屏幕比例，大小用倍数，全部存在 touch:layout 里。 */
var TL_DEFAULTS={dpad:{x:.15,y:.72,s:1.05},ab:{x:.87,y:.74,s:1.15},pills:{x:.5,y:.9,s:1.1},pause:{x:.94,y:.07,s:1}};
