function applyPauseCfg(){var el=document.getElementById('pause-button');if(!el)return;var p=(tlCfg&&tlCfg.pause)||TL_DEFAULTS.pause;el.style.left=(p.x*100)+'%';el.style.top=(p.y*100)+'%';el.style.right='auto';el.style.transformOrigin='50% 50%';el.style.transform='translate(-50%,-50%) scale('+p.s+')';}
