function icon(name){var shapes={search:'<circle cx="10" cy="10" r="7"/><path d="M15 15l6 6"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10l2 2M5 19l2-2M17 7l2-2"/>',back:'<path d="M20 12H4m6-6l-6 6 6 6"/>',pad:'<path d="M7 7h10c5 0 7 12 3 12l-5-3H9l-5 3C0 19 2 7 7 7z"/><path d="M7 10v5m-2-2h4m7-2h.1m3 3h.1"/>',save:'<path d="M4 3h13l4 4v14H3V3zM7 3v6h10V3M7 21v-8h10v8"/>',play:'<path d="M7 3l14 9-14 9z"/>'};return '<svg viewBox="0 0 24 24" aria-hidden="true">'+(shapes[name]||shapes.pad)+'</svg>';}
function btn(text,action,arg,cls,focus,disabled){return '<button class="'+(cls||'')+'" data-action="'+action+'" data-arg="'+esc(arg||'')+'" data-focus="'+esc(focus||action+':'+(arg||''))+'"'+(disabled?' disabled':'')+'>'+text+'</button>';}
function header(){var actions=state.page==='organize'?btn('取消整理','order-cancel')+btn(state.busy?'保存中…':'保存顺序','order-save','','primary','order-save:',state.busy):(state.page==='home'?btn('整理首页','organize'):'')+btn(icon('search')+'搜索','search')+btn(icon('settings')+'设置','settings');return '<header><div class="brand-icon" aria-hidden="true"></div><h1>童年游戏厅'+(window.ARCADE_PREVIEW?' · 测试版':'')+'</h1><div class="console-line" aria-hidden="true"></div><div class="header-actions">'+actions+'</div></header>';}
function footer(){var browse=state.page==='home'||state.page==='search'||state.page==='organize';var hints=state.page==='organize'?'<span><b class="key">方向</b>移动</span><span><b class="key">确定</b>拿起或放下</span><span><b class="key">返回</b>取消整理</span>':state.page==='gamepad'?'<span><b class="key">遥控器</b>方向移动</span><span><b class="key">确定</b>选择</span><span><b class="key">返回</b>上一级</span>':'<span><b class="key">方向</b>移动</span><span><b class="key">确定</b>打开</span><span><b class="key">返回</b>上一级</span>';if(touchCapable())hints='<span>点按选择</span><span>上下滑动浏览</span>';return '<footer><div class="key-hints">'+hints+'</div>'+(browse?'<div class="browse-controls" aria-label="浏览全部游戏">'+btn('上一屏','browse','-1')+'<span id="browse-position" aria-live="polite"></span>'+btn('下一屏','browse','1')+'</div>':'')+'<small>'+familyTotal()+'款游戏 · '+games.length+'个版本</small></footer>';}
function browseMetrics(){var main=app.querySelector('main');if(!main)return null;var cards=main.querySelectorAll('[data-action="detail"],[data-action="order-select"]'),step=main.clientHeight;for(var i=1;i<cards.length;i++){var row=cards[i].offsetTop-cards[0].offsetTop;if(row>5){step=row*Math.max(1,Math.floor(main.clientHeight/row));break;}}return {main:main,step:Math.max(1,step),max:Math.max(0,main.scrollHeight-main.clientHeight)};}
function updateBrowseDom(){var m=browseMetrics(),label=document.getElementById('browse-position');if(!m||!label)return;var total=Math.max(1,Math.ceil(m.max/m.step)+1),current=m.main.scrollTop>=m.max-2?total:Math.min(total,Math.floor((m.main.scrollTop+2)/m.step)+1);label.textContent=current+' / '+total;var prev=app.querySelector('[data-action="browse"][data-arg="-1"]'),next=app.querySelector('[data-action="browse"][data-arg="1"]');if(prev)prev.setAttribute('aria-disabled',m.main.scrollTop<=1?'true':'false');if(next)next.setAttribute('aria-disabled',m.main.scrollTop>=m.max-1?'true':'false');}
function scrollDom(direction){var m=browseMetrics();if(!m)return;m.main.scrollTop=Math.max(0,Math.min(m.max,m.main.scrollTop+direction*m.step));updateBrowseDom();}
function pageSize(){return state.page==='search'?6:(window.innerWidth<=800?8:10);}
function currentList(){var key=state.page+'|'+state.tab+'|'+state.query+'|'+state.players+'|'+state.genre+'|'+dataRev;if(listCache.key===key)return listCache.list;listCache.list=visibleGames();listCache.key=key;return listCache.list;}
function pageCount(){var n=currentList().length;return Math.max(1,Math.ceil(n/pageSize()));}
function updateBrowse(){if(state.page==='organize'){updateBrowseDom();return;}var label=document.getElementById('browse-position');if(!label)return;var total=pageCount(),page=Math.min(state.gridPage,total-1);if(page<0)page=0;state.gridPage=page;label.textContent=(page+1)+' / '+total;var prev=app.querySelector('[data-action="browse"][data-arg="-1"]'),next=app.querySelector('[data-action="browse"][data-arg="1"]');if(prev)prev.setAttribute('aria-disabled',page<=0?'true':'false');if(next)next.setAttribute('aria-disabled',page>=total-1?'true':'false');}
function scrollBrowse(direction){if(state.page==='organize'){scrollDom(direction);return;}var total=pageCount(),next=Math.max(0,Math.min(total-1,state.gridPage+direction));if(next===state.gridPage)return;state.gridPage=next;var list=currentList(),size=pageSize(),slice=list.slice(next*size,next*size+size),target=direction>0?slice[0]:slice[slice.length-1];render(target?'game:'+familyId(target):null);}
function title(name,back,extra){return '<div class="page-title">'+btn('← 返回'+(back||'游戏厅'),'back')+'<h2>'+name+'</h2>'+(extra?'<small>'+esc(extra)+'</small>':'')+'</div>';}
function screw(){return '<i class="screw left">+</i><i class="screw right">+</i>';}
function card(g,index){return '<button class="cartridge" data-index="'+(index===undefined?0:index)+'" data-action="detail" data-arg="'+esc(g.id)+'" data-focus="game:'+esc(familyId(g))+'"><span class="thumb"><img class="fg" loading="lazy" decoding="async" src="'+esc(g.art)+'" alt="'+esc(g.title)+'封面"></span><span class="label"><strong>'+esc(g.title)+'</strong><small>'+(ArcadeLib.isArcade(g)?'街机 · ':'')+esc(g.players)+(versionCount(g)>1?' · '+versionCount(g)+'个版本':'')+'</small>'+(g.aliases?'<small class="alt">'+esc(g.aliases)+'</small>':'')+'</span></button>';}
function gameBy(id){return games.filter(function(g){return g.id===id;})[0];}
function platformLabel(g){var names={neogeo:'Neo Geo',cps1:'CPS1',konami:'Konami',pgm:'IGS PGM',cps2:'CPS2',sega:'Sega',irem:'Irem',arcade:'通用'};return ArcadeLib.isSfc(g)?'Super Nintendo / SFC':ArcadeLib.isMd(g)?'Mega Drive / MD':ArcadeLib.isHandheld(g)?'Game Boy Advance / GBA':ArcadeLib.isArcade(g)?'街机 / '+names[g.system]:'FC / NES';}
function familyId(g){return g.group||g.id;}
var familyIndex=null,versionCounts=null,familyTotalCount=0,favoriteMap=null;
function buildFamilyIndex(){familyIndex={};versionCounts={};familyTotalCount=0;games.forEach(function(g){var id=familyId(g),list=familyIndex[id];if(!list)list=familyIndex[id]=[];list.push(g);});Object.keys(familyIndex).forEach(function(id){versionCounts[id]=familyIndex[id].length;familyTotalCount++;});}
function familyVersions(g){if(!familyIndex)buildFamilyIndex();return familyIndex[familyId(g)]||[g];}
function versionCount(g){if(!versionCounts)buildFamilyIndex();return versionCounts[familyId(g)]||1;}
function familyTotal(){if(!versionCounts)buildFamilyIndex();return familyTotalCount;}
function invalidateList(){dataRev++;listCache.key='';}
function resetVersionCounts(){familyIndex=null;versionCounts=null;familyTotalCount=0;invalidateList();}
function uniqueGames(list){var seen={},out=[];list.forEach(function(g){var id=familyId(g);if(!seen[id]){seen[id]=true;out.push(g);}});return out;}
function isFavorite(g){if(!favoriteMap){favoriteMap={};state.prefs.favorites.forEach(function(id){favoriteMap[id]=1;});}return !!favoriteMap[familyId(g)];}
function chooseVersion(){var current=state.current,versions=familyVersions(current),selected=versions.indexOf(current);var buttons=versions.map(function(g){return {text:g.version+(g===current?' · 当前':''),primary:g===current,fn:function(){showDetail(g.id);}};});buttons.push({text:'返回游戏详情',fn:function(){render('versions:');}});dialog('选择游戏版本','<p>同一游戏的不同版本独立保存进度。切换版本不会覆盖已有存档。</p>',buttons,selected);}

function searchMatch(g){var words=String(state.query||'').toLowerCase().replace(/^\s+|\s+$/g,'').split(/\s+/);if(words.length===1&&!words[0])return true;var hay=[g.title,g.aliases,g.genre,g.players,g.version,g.id,g.group].map(function(v){return String(v===undefined||v===null?'':v).toLowerCase();}).join(' ');for(var i=0;i<words.length;i++)if(words[i]&&hay.indexOf(words[i])<0)return false;return true;}
function visibleGames(){var recentMap=null,rank=null;var out=games.filter(function(g){if(state.page==='search')return searchMatch(g)&&(state.players==='全部'||g.players===state.players)&&(state.genre==='全部'||g.genre===state.genre);if(state.tab==='红白机')return !g.system||g.system==='nes';if(state.tab==='街机')return ArcadeLib.isArcade(g);if(state.tab==='GBA')return ArcadeLib.isHandheld(g);if(state.tab==='MD')return ArcadeLib.isMd(g);if(state.tab==='SFC')return ArcadeLib.isSfc(g);if(state.tab==='双人合作')return g.players==='双人合作';if(state.tab==='我的收藏')return isFavorite(g);if(state.tab==='最近玩过'){if(!recentMap){recentMap={};state.prefs.recent.forEach(function(id){recentMap[id]=1;});}return !!recentMap[g.id];}return true;});if(state.page==='home'&&state.tab==='最近玩过'){rank={};state.prefs.recent.forEach(function(id,i){rank[id]=i;});out.sort(function(a,b){var ra=rank[a.id]===undefined?9999:rank[a.id],rb=rank[b.id]===undefined?9999:rank[b.id];return ra-rb;});}else out=ArcadeLib.sortHomeGames(out,games,state.prefs.homeOrder);return uniqueGames(out);}
function resumeBanner(){var r=state.lastPlaySave;if(!r||!r.game)return '';var g=r.game;return '<section class="resume-banner" aria-label="继续上次游戏"><div class="resume-copy"><small>继续游戏</small><strong>'+esc(g.title)+'</strong><span>'+platformLabel(g)+' · '+formatTime(r.time||Date.now())+' · '+(r.slot==='auto'?'自动存档':(Number(r.slot)===0?'快速存档':'存档 '+r.slot))+'</span></div><div class="resume-actions">'+btn('继续','continue-last','','primary','continue-last:')+btn('忽略','ignore-last','','','ignore-last:')+'</div></section>';}
function refreshLastPlay(){var lp=state.prefs.lastPlay;if(!lp||!lp.id){state.lastPlaySave=null;return Promise.resolve();}var g=gameBy(lp.id);if(!g){state.lastPlaySave=null;return Promise.resolve();}var slot=lp.slot==='auto'?'auto':Number(lp.slot);if(slot!=='auto'&&isNaN(slot)){state.lastPlaySave=null;return Promise.resolve();}return Store.get('slot:'+g.hash+':'+slot).then(function(s){if(!s){state.lastPlaySave=null;return;}state.lastPlaySave={game:g,slot:slot,time:s.time||lp.time};if(state.page==='home')render();}).catch(function(){state.lastPlaySave=null;});}
function renderHome(){var tabs=['全部游戏','红白机'];if(games.some(function(g){return ArcadeLib.isArcade(g);}))tabs.push('街机');if(games.some(function(g){return ArcadeLib.isHandheld(g);}))tabs.push('GBA');if(games.some(function(g){return ArcadeLib.isMd(g);}))tabs.push('MD');if(games.some(function(g){return ArcadeLib.isSfc(g);}))tabs.push('SFC');tabs=tabs.concat(['双人合作','我的收藏','最近玩过']);var nav='<nav'+(tabs.length>6?' class="nav-many"':'')+'>'+tabs.map(function(t){return btn(esc(t),'tab',t,t===state.tab?'selected':'');}).join('')+'</nav>';var list=currentList(),size=pageSize(),total=Math.max(1,Math.ceil(list.length/size));if(state.gridPage>=total)state.gridPage=total-1;if(state.gridPage<0)state.gridPage=0;var base=state.gridPage*size,slice=list.slice(base,base+size);return nav+resumeBanner()+'<main id="scroll-main">'+(list.length?'<div class="grid">'+slice.map(function(g,i){return card(g,base+i);}).join('')+'</div>':'<div class="empty"><h2>'+ (state.tab==='我的收藏'?'还没有收藏的游戏':'这里还没有游戏')+'</h2><p>'+(state.tab==='我的收藏'?'在游戏详情里选择“加入收藏”，游戏就会出现在这里。':state.tab==='最近玩过'?'开始玩过的游戏会自动出现在这里。':'这个平台还没有游戏，可以从文件夹导入。')+'</p>'+(games.length?btn('查看全部游戏','tab','全部游戏','primary'):btn('导入自己的NES游戏','import-games','','primary'))+'</div>')+'</main>';}
function startOrganize(){state.orderDraft=ArcadeLib.resolveHomeOrder(games,state.prefs.homeOrder);state.orderSelected=state.orderDraft[0]||null;state.orderMoving=false;state.page='organize';render(state.orderSelected?'order:'+state.orderSelected:'order-save:');}
function orderDirty(){return JSON.stringify(state.orderDraft)!==JSON.stringify(ArcadeLib.resolveHomeOrder(games,state.prefs.homeOrder));}
function closeOrganize(){state.orderDraft=null;state.orderSelected=null;state.orderMoving=false;state.dragOrder=null;state.page='home';state.tab='全部游戏';state.gridPage=0;render('organize:');}
function cancelOrganize(){if(!orderDirty())return closeOrganize();dialog('放弃这次整理？','<p>还没有保存，原来的首页顺序会保留。</p>',[{text:'继续整理',primary:true,fn:function(){render('order:'+state.orderSelected);}},{text:'放弃更改',fn:closeOrganize}]);}
function moveOrder(index,focus){state.orderDraft=ArcadeLib.moveHomeGame(state.orderDraft,state.orderSelected,index);if(focus.indexOf('order:')!==0)state.orderMoving=false;render(focus);}
function orderColumns(){var cards=app.querySelectorAll('[data-action="order-select"]');if(!cards.length)return 1;for(var i=1;i<cards.length;i++)if(cards[i].offsetTop>cards[0].offsetTop+5)return i;return cards.length;}
