function wizardPadName(key){var list=gamepadList()||[];for(var i=0;i<list.length;i++)if(list[i].key===key)return list[i].name||'已连接手柄';return '已连接手柄';}
function requestWizardCapture(){var w=state.wizard,steps=w&&(w.steps||WIZ_STEPS);if(!w||w.step>=steps.length)return;if(native&&native.nativeGamepadCapture)native.nativeGamepadCapture(w.pad,steps[w.step][1]);}
function startWizard(padKey){if(!native||!native.nativeGamepadCapture){toast('电视上才能识别手柄布局');return;}gamepadCapture=null;state.dialog=null;state.page='gp-wizard';state.wizard={pad:padKey,step:0,done:{},steps:WIZ_STEPS.slice()};render('gp-wizard-cancel:');requestWizardCapture();}
