function orderTarget(target){while(target&&target!==app){if(target.getAttribute&&target.getAttribute('data-action')==='order-select')return target;target=target.parentNode;}return null;}
app.addEventListener('dragstart',function(e){var el=orderTarget(e.target);if(state.page!=='organize'||state.busy||!el)return;state.dragOrder=el.getAttribute('data-arg');if(e.dataTransfer){e.dataTransfer.setData('text/plain',state.dragOrder);e.dataTransfer.effectAllowed='move';}el.classList.add('dragging');},false);
